('<lesson_id>', 'quiz', replace($blk${"title": "Прочитай предложение и выбери пропущенное слово", "questions": [{"q": "This T-shirt is ___ than that at the department store.", "type": "single", "options": [{"text": "more cheap"}, {"text": "cheaper"}, {"text": "the cheapest"}], "correct": [1]}, {"q": "The shopping bag isn't ___ for all these things.", "type": "single", "options": [{"text": "big enough"}, {"text": "too big"}, {"text": "big too"}], "correct": [0]}, {"q": "The cashier is ___ the one at the baker's.", "type": "single", "options": [{"text": "as friendlier as"}, {"text": "not as friendliest as"}, {"text": "as friendly as"}], "correct": [2]}, {"q": "This sports shop is ___ in our town.", "type": "single", "options": [{"text": "more expensive"}, {"text": "the most expensive"}, {"text": "the expensivest"}], "correct": [1]}, {"q": "The queue is ___, let's come back later.", "type": "single", "options": [{"text": "long enough"}, {"text": "the longest"}, {"text": "too long"}], "correct": [2]}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 2),
