('<lesson_id>', 'order', replace($blk${"words": ["They", "pay", "in cash", "at the greengrocer's."], "sentence": "They pay in cash at the greengrocer's.", "audio_tts": "They pay in cash at the greengrocer's."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 4),
('<lesson_id>', 'order', replace($blk${"words": ["This", "is", "the biggest", "department store", "in our city."], "sentence": "This is the biggest department store in our city.", "audio_tts": "This is the biggest department store in our city."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 5),
('<lesson_id>', 'order', replace($blk${"words": ["He", "isn't", "old enough", "to pay", "by card."], "sentence": "He isn't old enough to pay by card.", "audio_tts": "He isn't old enough to pay by card."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 6),
